import { founder } from "@/data/founder";
import { figures, media, marqueeWords, personal, speakingTopics } from "@/data/extras";
import Reveal from "../animations/Reveal";
export function NumbersStrip() { return <section className="border-y border-ink/15 px-5 py-10 md:px-10"><div className="mx-auto grid max-w-[1440px] grid-cols-3 gap-4">{figures.map((f,i)=><div key={i} className="text-center"><p className="font-serif text-4xl text-bronze md:text-6xl">{f.value}</p><p className="mt-2 text-xs text-stone">{f.label}</p></div>)}</div></section>; }
export function Marquee() { return <div className="overflow-hidden bg-bronze py-5 text-ink" aria-label="Values"><div className="marquee-track flex w-max gap-12" aria-hidden="true">{[...marqueeWords,...marqueeWords,...marqueeWords].map((w,i)=><span key={i} className="font-serif text-3xl">{w}<span className="pl-12">✳</span></span>)}</div></div>; }
export function PersonalSection() { if (!founder.showPersonal) return null; return <section className="px-5 py-24 md:px-10 md:py-40"><div className="mx-auto grid max-w-[1440px] gap-12 md:grid-cols-12"><div className="md:col-span-7"><Reveal><h2 className="h2">The Person Behind the Profession.</h2></Reveal><div className="mt-12 grid grid-cols-2 items-start gap-4">{personal.images.map((im,i)=><div key={i} className={`relative min-h-36 bg-gradient-to-br from-stone/35 to-bronze/35 ${i===1?"mt-10 aspect-[4/5]":"aspect-square"}`}><span className="absolute bottom-2 left-2 text-xs text-paper/70">{im}</span></div>)}</div></div><div className="space-y-10 md:col-span-4 md:col-start-9 md:pt-24"><div><p className="text-xs uppercase tracking-widest text-stone">Interests</p><ul className="mt-4">{personal.interests.map(x=><li key={x} className="border-t border-ink/15 py-3 font-serif text-2xl">{x}</li>)}</ul></div><div><p className="text-xs uppercase tracking-widest text-stone">Sources of inspiration</p><ul className="mt-4">{personal.inspirations.map(x=><li key={x} className="border-t border-ink/15 py-3 font-serif text-2xl">{x}</li>)}</ul></div></div></div></section>; }
export function MediaSection() { if (!media.length) return null; return <section className="bg-ink px-5 py-24 text-paper md:px-10 md:py-32"><div className="mx-auto max-w-[1440px]"><Reveal><h2 className="h2">In the Press and in Conversation.</h2></Reveal><ul className="mt-12">{media.map((m,i)=><li key={i} className="border-t border-paper/20"><a href={m.href} className="grid gap-2 py-6 hover:text-bronze md:grid-cols-12 md:items-baseline"><span className="text-sm text-paper/50 md:col-span-3">{m.outlet}</span><span className="font-serif text-2xl md:col-span-6">{m.title}</span><span className="text-sm text-paper/50 md:col-span-3 md:text-right">{m.date} ↗</span></a></li>)}</ul></div></section>; }
export function SpeakingSection() { return <section className="px-5 py-24 md:px-10 md:py-36"><div className="mx-auto grid max-w-[1440px] gap-10 md:grid-cols-12"><h2 className="h2 md:col-span-6">Ideas worth sharing.</h2><div className="md:col-span-5 md:col-start-8"><p className="text-sm text-stone">Speaking &amp; collaboration</p><ul className="mt-6">{speakingTopics.map(x=><li key={x} className="border-t border-ink/20 py-4 font-serif text-2xl">{x}</li>)}</ul><a href="#contact" className="mt-8 inline-block border-b border-bronze pb-1 text-sm">Invite Richi to speak</a></div></div></section>; }
export function NewsletterSection() { return <section className="bg-ink px-5 py-20 text-paper md:px-10"><div className="mx-auto flex max-w-[1440px] flex-col gap-8 md:flex-row md:items-end md:justify-between"><div><p className="text-xs uppercase tracking-widest text-bronze">Occasional notes</p><h2 className="mt-3 font-serif text-4xl">Stay in the loop.</h2></div><form action={`mailto:${founder.email}`} method="get" className="flex w-full max-w-xl border-b border-paper/35"><label className="sr-only" htmlFor="newsletter-email">Email address</label><input id="newsletter-email" type="email" name="subject" placeholder="Your email address" required className="min-w-0 flex-1 bg-transparent py-4 text-sm placeholder:text-paper/50 focus:outline-none"/><button className="py-4 text-sm text-bronze">Join ↗</button></form></div>{/* TODO: connect this form to a newsletter backend. */}</section>; }
